DEFAULT_PROJECT_DIR = Path(__file__).resolve().parent / "PatchProof"
BACKEND_HOST = "127.0.0.1"
BACKEND_PORT = 5000
FRONTEND_HOST = "127.0.0.1"
FRONTEND_PORT = 5173


def say(message: str) -> None:
    print(f"[PatchProof] {message}", flush=True)


def embedded_archive() -> bytes:
    try:
        raw = base64.b64decode("".join(BUNDLE_B64.split()), validate=True)
    except Exception as exc:
        raise RuntimeError(f"The embedded project payload is damaged: {exc}") from exc
    digest = hashlib.sha256(raw).hexdigest()
    if digest != BUNDLE_SHA256:
        raise RuntimeError("Embedded project integrity check failed (SHA-256 mismatch).")
    return raw


def safe_extract_project(project_dir: Path, force: bool = False) -> Path:
    archive_bytes = embedded_archive()
    marker = project_dir / ".patchproof_launcher.json"
    project_dir = project_dir.expanduser().resolve()

    if marker.is_file() and not force:
        try:
            current = json.loads(marker.read_text(encoding="utf-8"))
        except Exception:
            current = {}
        if current.get("bundle_sha256") == BUNDLE_SHA256:
            say(f"Project already extracted: {project_dir}")
            return project_dir

    if project_dir.exists() and any(project_dir.iterdir()) and not marker.exists() and not force:
        raise RuntimeError(
            f"The target directory already contains files: {project_dir}\n"
            "Choose another location with --project-dir, or use --force-extract "
            "to merge/overwrite the files included in this bundle."
        )

    project_dir.mkdir(parents=True, exist_ok=True)
    try:
        with zipfile.ZipFile(BytesIO(archive_bytes), "r") as zf:
            bad = zf.testzip()
            if bad:
                raise RuntimeError(f"Embedded ZIP failed CRC validation at {bad}")
            for info in zf.infolist():
                if info.is_dir():
                    continue
                member = PurePosixPath(info.filename)
                if member.is_absolute() or ".." in member.parts or not member.parts:
                    raise RuntimeError(f"Unsafe path in embedded ZIP: {info.filename}")
                # The distribution archive has a single top-level PatchProof/ folder.
                parts = member.parts[1:] if member.parts[0] == "PatchProof" else member.parts
                if not parts:
                    continue
                destination = project_dir.joinpath(*parts).resolve()
                if project_dir != destination and project_dir not in destination.parents:
                    raise RuntimeError(f"Extraction path escaped project directory: {info.filename}")
                destination.parent.mkdir(parents=True, exist_ok=True)
                with zf.open(info, "r") as src, destination.open("wb") as dst:
                    shutil.copyfileobj(src, dst)
    except zipfile.BadZipFile as exc:
        raise RuntimeError(f"Embedded project ZIP is invalid: {exc}") from exc

    marker.write_text(
        json.dumps({"bundle_sha256": BUNDLE_SHA256, "launcher": "PatchProof.py", "version": "4.0"}, indent=2),
        encoding="utf-8",
    )
    required = [
        project_dir / "backend" / "app.py",
        project_dir / "frontend" / "package.json",
        project_dir / "requirements.txt",
        project_dir / "README.md",
    ]
    missing = [str(path) for path in required if not path.is_file()]
    if missing:
        raise RuntimeError("The extracted project is incomplete: " + ", ".join(missing))
    say(f"Project extracted and verified: {project_dir}")
    return project_dir


def run_checked(command: list[str], cwd: Path, label: str) -> None:
    say(label)
    try:
        result = subprocess.run(command, cwd=str(cwd), check=False)
    except FileNotFoundError as exc:
        raise RuntimeError(f"Required command not found for {label}: {command[0]}") from exc
    if result.returncode != 0:
        raise RuntimeError(f"{label} failed with exit code {result.returncode}.")


def python_environment(project_dir: Path, skip_install: bool) -> Path:
    if skip_install:
        say("Skipping Python dependency installation and using the current interpreter (--skip-install).")
        return Path(sys.executable)
    venv_dir = project_dir / ".venv"
    if os.name == "nt":
        python_exe = venv_dir / "Scripts" / "python.exe"
    else:
        python_exe = venv_dir / "bin" / "python"
    if not python_exe.exists():
        say("Creating the project's Python virtual environment…")
        venv.EnvBuilder(with_pip=True).create(venv_dir)
    run_checked(
        [str(python_exe), "-m", "pip", "install", "--disable-pip-version-check", "-r", "requirements.txt"],
        project_dir,
        "Installing Flask and backend dependencies…",
    )
    return python_exe


def node_and_npm() -> tuple[str, str]:
    node = shutil.which("node")
    npm = shutil.which("npm")
    if not node or not npm:
        raise RuntimeError(
            "Node.js and npm are required for the React frontend. Install Node.js 22.12+ "
            "from https://nodejs.org/, reopen PowerShell, then run PatchProof.py again. "
            "Use --backend-only if you only want to start Flask."
        )
    try:
        version_text = subprocess.check_output([node, "--version"], text=True, stderr=subprocess.STDOUT).strip()
        match = re.search(r"v?(\d+)\.(\d+)\.(\d+)", version_text)
        version = tuple(map(int, match.groups())) if match else (0, 0, 0)
        if version < (22, 12, 0):
            raise RuntimeError(f"Node.js {version_text} is too old. Install Node.js 22.12 or newer.")
    except subprocess.CalledProcessError as exc:
        raise RuntimeError("Could not determine the installed Node.js version.") from exc
    return node, npm


def install_frontend(frontend_dir: Path, skip_install: bool) -> str:
    _node, npm = node_and_npm()
    if not skip_install and not (frontend_dir / "node_modules").is_dir():
        if os.name == "nt":
            command = f'"{npm}" install --no-audit --no-fund'
            say("Installing React/Vite dependencies (first run only)…")
            result = subprocess.run(command, cwd=str(frontend_dir), shell=True, check=False)
            if result.returncode != 0:
                raise RuntimeError(f"npm install failed with exit code {result.returncode}.")
        else:
            run_checked([npm, "install", "--no-audit", "--no-fund"], frontend_dir, "Installing React/Vite dependencies (first run only)…")
    elif skip_install:
        say("Skipping npm dependency installation (--skip-install).")
    elif (frontend_dir / "node_modules").is_dir():
        say("React dependencies already installed.")
    return npm


def wait_for_http(url: str, process: subprocess.Popen, label: str, timeout: float = 35.0) -> None:
    deadline = time.monotonic() + timeout
    last_error = "not started yet"
    while time.monotonic() < deadline:
        if process.poll() is not None:
            raise RuntimeError(f"{label} exited early with code {process.returncode}.")
        try:
            with urllib.request.urlopen(url, timeout=1.5) as response:
                if response.status < 500:
                    say(f"{label} is ready.")
                    return
        except Exception as exc:
            last_error = str(exc)
        time.sleep(0.4)
    raise RuntimeError(f"Timed out waiting for {label}: {last_error}")


def terminate_processes(processes: list[subprocess.Popen]) -> None:
    for process in processes:
        if process.poll() is None:
            try:
                process.terminate()
            except Exception:
                pass
    for process in processes:
        if process.poll() is None:
            try:
                process.wait(timeout=5)
            except Exception:
                try:
                    process.kill()
                except Exception:
                    pass


def start_app(project_dir: Path, args: argparse.Namespace) -> int:
    processes: list[subprocess.Popen] = []
    python_exe = python_environment(project_dir, args.skip_install)

    env = os.environ.copy()
    env.setdefault("PATCHPROOF_HOST", BACKEND_HOST)
    env.setdefault("PATCHPROOF_PORT", str(BACKEND_PORT))

    say("Starting Flask backend at http://127.0.0.1:5000 …")
    backend = subprocess.Popen(
        [str(python_exe), str(project_dir / "backend" / "app.py")],
        cwd=str(project_dir), env=env,
    )
    processes.append(backend)

    frontend_url = f"http://{FRONTEND_HOST}:{FRONTEND_PORT}"
    backend_url = f"http://{BACKEND_HOST}:{BACKEND_PORT}"
    try:
        wait_for_http(backend_url + "/health", backend, "Flask backend")
        if not args.backend_only:
            npm = install_frontend(project_dir / "frontend", args.skip_install)
            say("Starting React/Vite frontend at " + frontend_url + " …")
            if os.name == "nt":
                command = f'"{npm}" run dev -- --host 127.0.0.1'
                frontend = subprocess.Popen(command, cwd=str(project_dir / "frontend"), env=env, shell=True)
            else:
                command = [npm, "run", "dev", "--", "--host", "127.0.0.1"]
                frontend = subprocess.Popen(command, cwd=str(project_dir / "frontend"), env=env)
            processes.append(frontend)
            # Vite's root page is sufficient as a startup check; actual API calls proxy to Flask.
            wait_for_http(frontend_url, frontend, "React/Vite frontend")
            open_url = frontend_url
        else:
            say("Backend-only mode selected. React/Vite frontend was not started.")
            open_url = backend_url

        say("PatchProof is running. Press Ctrl+C in this window to stop both servers.")
        say("Open: " + open_url)
        if not args.no_browser:
            try:
                import webbrowser
                webbrowser.open(open_url)
            except Exception:
                pass

        while True:
            for process in processes:
                code = process.poll()
                if code is not None:
                    say(f"A service stopped (exit code {code}); stopping the other service.")
                    return code
            time.sleep(0.5)
    except KeyboardInterrupt:
        say("Stopping PatchProof…")
        return 0
    finally:
        terminate_processes(processes)


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Extract and launch the complete PatchProof project.")
    parser.add_argument("--project-dir", type=Path, default=DEFAULT_PROJECT_DIR, help="directory for the extracted project")
    parser.add_argument("--extract-only", action="store_true", help="extract and validate without starting services")
    parser.add_argument("--backend-only", action="store_true", help="start Flask only; do not start Vite")
    parser.add_argument("--skip-install", action="store_true", help="skip pip/npm dependency installation")
    parser.add_argument("--no-browser", action="store_true", help="do not open a browser after startup")
    parser.add_argument("--force-extract", action="store_true", help="overwrite bundled files in the target project directory")
    return parser.parse_args()


def main() -> int:
    args = parse_args()
    try:
        project_dir = safe_extract_project(args.project_dir, force=args.force_extract)
        if args.extract_only:
            say("Extraction-only mode complete. See README.md in the project folder.")
            return 0
        return start_app(project_dir, args)
    except Exception as exc:
        say("ERROR: " + str(exc))
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
